def is_multiply_prime(a):
    def is_prime(n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    if a < 2:
        return False

    primes = []
    temp = a
    for i in range(2, int(a**0.5) + 1):
        if temp % i == 0 and is_prime(i):
            other_factor = a // i
            if other_factor != i and is_prime(other_factor):
                primes.append(i)
                primes.append(other_factor)
                break
        if temp == 1:
            break

    if len(primes) == 2 and primes[0] * primes[1] == a:
        return True

    # Check for cases where a is product of three primes (e.g., 30 = 2 * 3 * 5)
    if a > 2:
        for i in range(2, int(a**0.5) + 1):
            if is_prime(i) and a % i == 0:
                remaining = a // i
                if is_prime(remaining):
                    return True

    return False
